<?php require 'config.php';require 'auth.php';if(!empty($_SESSION['user'])){header('Location:index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('SELECT user_id,full_name,username,password_hash,role FROM users WHERE username=? AND is_active=1');$q->execute([trim($_POST['username']??'')]);$u=$q->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;header('Location:index.php');exit;}$err='Username atau password tidak tepat.';}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | AutoDyno</title><link rel="stylesheet" href="assets/style.css"></head><body class="login-body"><section class="login-visual"><div class="login-logo">⚙</div><h1>AutoDyno</h1><p>Warehouse & Production Management System</p><div class="visual-card"><span>◉</span><div><b>Production ready</b><small>Pantau material hingga produk jadi</small></div></div></section><section class="login-panel"><form method="post" class="login-form"><div class="mobile-brand">⚙ AutoDyno</div><span class="eyebrow">SELAMAT DATANG</span><h2>Masuk ke akun Anda</h2><p>Masukkan data akses untuk melanjutkan.</p><?php if($err):?><div class="alert error">! <?=e($err)?></div><?php endif?><label>Username<input name="username" autocomplete="username" placeholder="Masukkan username" required autofocus></label><label>Password<input type="password" name="password" autocomplete="current-password" placeholder="Masukkan password" required></label><button class="primary full" type="submit">Masuk ke sistem <span>→</span></button><small class="login-note">Akses sistem hanya untuk pengguna terdaftar.</small></form></section></body></html>